    "notes": "Популярность модели 757 Cityhunter побудила Nova Arms выпустить другое оружие под той же торговой маркой. Ни одно из новых видов оружия не отошло дальше от концепции 757-го, чем Cityhunter X. Несмотря на то, что это хорошо продуманный пистолет, решение превратить Cityhunter X в пистолет с магазинным заряжанием вместо револьвера устранило большую часть фактора крутости. Поклонники огнестрельного оружия обычно отказываются от названия Cityhunter и вместо этого называют его Nova X.\nТяжелый пистолет отличного качества.\n\nПараметры источника: Навык: Пистолет; Урон: 3d6; Магазин: 8 Т Пистолет; ROF: 2; Руки: 1; Слотов модификации: 3; Можно Скрыть: ДА; Цена: 500eb (Дорого)",
