    "concealable": false,
    "costEb": 500,
    "notes": "Используя магниты для решения давней проблемы, ElectroMag может сжимать или разделять металлическую дробь внутри заряженных боеприпасов, позволяя пользователю выбирать между дробью и жаканом на лету.\nДробовик стандартного качества, стреляющий специально изготовленными Магнитными зажигательными боеприпасами или Магнитными базовыми боеприпасами для дробовика. Этот боеприпас необходимо приобретать специально для этого оружия, и он стоит так же, как и его немагнитные аналоги. Каждый раз, когда пользователь совершает проверку атаки с помощью ElectroMag, он выбирает, будут ли боеприпасы действовать как жакан или дробь.\n\nПараметры источника: Навык: Тактическое; Урон: 3d6 5d6; Магазин: 4 Дробовик; ROF: 1; Руки: 2; Слотов Модификаций: 2; Можно скрыть: НЕТ; Цена: 500eb (Дорого)",
