    "notes": "Политехнический институт Дарры выходит на рынки в основном через кочевников-мореплавателей, импортирующих из Азиатско-Тихоокеанского региона. Binary представляет собой классическую конструкцию штурмовой винтовки в сочетании с подствольным гранатометом.\nШтурмовая винтовка стандартного качества. Оснащена\nподствольным гранатометом.\n\nПараметры источника: Навык: Автоогонь, / Ор.кр.калибра, / Тактическое; Урон: 5d6 6d6; Магазин: 25 Винтовка, / 1 Граната; ROF: 1; Руки: 2; Слотов Модификаций: 1; Можно скрыть: НЕТ; Цена: 1000eb (Очень Дорого)",
