    "notes": "Разновидность Militech Ronin Light Assault, Hyperlight продается силам безопасности, которые в первую очередь имеют дело с плохо бронированными угрозами. Малый вес облегчает управление винтовкой, но снижает эффективность каждого выстрела.\nШтурмовая винтовка отличного качества, наносящая 4d6 урона при одиночном выстреле. Поставляется с установленным увеличенным магазином.\n\nПараметры источника: Навык: Автоогонь, / Тактическое; Урон: 4d6; Магазин: 35 Винтовка; ROF: 1; Руки: 2; Слотов Модификаций: 2; Можно скрыть: НЕТ; Цена: 600eb (Дорого)",
