    "concealable": false,
    "costEb": 1000,
    "notes": "Рабочая реплика главного героя милого спортивного аниме от Sanroo — Лучшие Друзья Навсегда: Баллистические Напарники. Инженера Косиро Юдзу заставили работать над проектом в одиночку под давлением безумного двухнедельного дедлайна — это было формой производственного буллинга. В отместку своим начальникам он превратил оружие в инженерный шедевр, оставив внутри магазина отпечаток в форме цитрусового плода.\nЭто штурмовая винтовка Отличного качества. Пользователь может установить или извлечь одноручное дальнобойное оружие (необязательно скрываемое до установки), чтобы оно было спрятано в корпусе винтовки — без необходимости совершать проверку на скрытность. Установленное оружие можно доставать и убирать без траты действия. Когда оно «всплывает», спусковой крючок винтовки срабатывает на встроенное оружие. Прицелы и обвесы для одного оружия не влияют на другое, и перезаряжаются они отдельно.\n\nПараметры источника: Навык: Автоогонь, / Тактическое; Урон: 5d6; Магазин: 25 Винтовка; ROF: 1; Руки: 2; Слотов Модификаций: 2; Можно скрыть: НЕТ; Цена: 1000eb (Очень Дорого)",
