    "notes": "Любой боеприпас,Стреляет стрелами\n\nЭкзотическая снайперская винтовка с 8 патронами, наносящая 4d6 урона с одного выстрела. Вместо пуль она стреляет стрелами и способна заряжаться всеми доступными боеприпасами, несмотря на то, что является экзотическим оружием.\nИсточник: 12ДнейКибероруждества\n\nПараметры источника: Навык: Тактическое; Урон: 4d6; Магазин: 8 Стрела; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 500eb / (Дорогое)",
