    "notes": "Автоогонь(4),\nЛюбой боеприпас\n\nЭРРАТОЙ УБРАН ТЕГ ЭКЗОТИЧЕСКОЕ\nШтурмовая винтовка с магазином в 35 патронов и Коннектором Смартлинка.\nИсточник: 12ДнейКибероруждества\n\nПараметры источника: Навык: Автоогонь / Тактическое; Урон: 5d6; Магазин: 30 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)\n\nRTG Weapon Rebalance (июль 2026): ёмкость магазина исправлена на 35 патронов.",
