    "concealable": false,
    "costEb": 100,
    "notes": "Автоогонь(4),\nЛюбой боеприпас,\nПлохого качества\n\nЭРРАТОЙ УБРАН ТЕГ ЭКЗОТИЧЕСКОЕ\nШтурмовая винтовка низкого качества с магазином на 20 патронов. Если оружие заклинило, то вероятность продолжения работы и автоматического устранения заклинивания в обычном режиме составляет 50%. Если вы проиграете в броске монетки, оружие не выстрелит, и нужно использовать действие, чтобы устранить клин.\nИсточник: 12ДнейКибероруждества\n\nПараметры источника: Навык: Автоогонь / Тактическое; Урон: 5d6; Магазин: 20 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 100eb / (Премиум)",
