    "notes": "Взрывы,\nСигнальная Ракета\n\nОдноручный экзотический гранатомет, рассчитанный на один выстрел. Слишком громоздкий, чтобы установить его в откидной киберимплант. В дополнение ко всем гранатным боеприпасам, ракетница может стрелять сигнальными ракетами, используя таблицу дальности гранатомета. Эти сигнальные ракеты не взрываются и не наносят урона, но в воздухе их можно увидеть на расстоянии до 3 километров. После приземления они действуют как обычные сигнальные ракеты.\nИсточник: Гараж Вудчипер\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 6d6; Магазин: 1 Граната; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 100eb / (Премиум)",
