    "costEb": 1000,
    "notes": "Дробь 4к6,\nНелетальное оружие\n\nЭкзотический дробовик низкого качества, стреляющий с помощью навыка \"Оружие Крупного Калибра\" вместо навыка \"Тактическое оружие\". Милитех Эгида — это дробовик, который может стрелять только из альтернативного режима стрельбы \"Выстрел Дробью\", но при этом наносит 4d6 вместо 3d6 урона. Кроме того, вместо боеприпасов при стрельбе из этого оружия расходуется один из 8 зарядов из само-перезаряжаемого (1 час) блока батарей. Урон, наносимый этим оружием, не может вызвать критическое ранение и не разрушает броню. Если урон, нанесенный этим оружием, уменьшил бы ПЗ цели до 1, то вместо этого она теряет сознание на 1 ПЗ.\nИсточник: Гараж Вудчипер\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 4d6; Магазин: 8 Батарея; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
