    "notes": "Ор.Бл.Боя,\nпо СЛ лука\n\nДвуручное экзотическое очень тяжелое оружие ближнего боя. Этот огромный гарпун может быть выпущен из своего уникального баллистического корпуса с помощью навыка \"\"Оружие Крупного Калибра\"\" с использованием таблицы\nдальности для луков и арбалетов. При выстреле он продолжает игнорировать половину брони цели. После выстрела гарпун может использовать любой человек в качестве экзотического очень тяжелого оружие ближнего боя. Если его вернуть, то с помощью действия его можно \"\"перезарядить\"\" в свой баллистический корпус.\nИсточник: Гараж Вудчипер\n\nПараметры источника: Навык: Ор.Бл.Боя / Ор.кр.калибра; Урон: 4d6; Магазин: 1; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
