    "costEb": 1000,
    "notes": "Дробь 3d6,\nЗажигательный Боеприпас,\nРазрывнойВыстрел\n\nЭкзотический дробовик, стреляющий с помощью навыка \"\"Оружие Крупного Калибра\"\" вместо навыка \"\"Тактическое оружие\"\". Механически огнемет представляет собой дробовик, который может стрелять только зажигательными\nснарядами (стоимость боеприпасов такая же, как и у зажигательных снарядов). Помимо основного урона, ваши цели загораются и продолжают гореть, до тех пор, пока они не используют действие, чтобы потушить себя, они получают 4 урона напрямую в ПЗ в конце своего хода. Если они уже горели, эффект поджигания увеличивает интенсивность горения на бОльшую. Несколько раз этот эффект не суммируется. Урон, наносимый этим оружием, не может вызвать критическое ранение, и его нельзя использовать для прицельных выстрелов.\nРазрывной Огномёт также имеет уникальный альтернативный режим стрельбы. Израсходовав все оставшиеся боеприпасы из обоймы, вы можете выстрелить огненным шаром, используя навык \"\"Оружие Крупного Калибра\"\", который взрывается как зажигательная граната. При использовании этого альтернативного режима стрельбы используйте таблицу дальности гранатомета. Когда вы используете этот альтернативный режим стрельбы, вы сразу же начитаете гореть со смертельной интенсивностью.\nИсточник: Гараж Вудчипер\n\nПараметры источника: Навык: Ор.кр.калибра; Урон: 3d6; Магазин: 1 Дробовик; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
