    "notes": "Автоогонь(4),\nСошки,\nТребуется ТЕЛ 11+\n\nЭкзотическая штурмовая винтовка, если совершается одиночный выстрел, то применяется навык Оружие Крупного Калибра. Огромный коробчатый магазин вмещает 500 патронов. Для стрельбы из этого оружия требуется ТЕЛ 11 или выше, если оно не закреплено.\nВ качестве действия сошки могут быть развернуты и установлены на поверхность. Это означает, что оружие считается закрепленным до тех пор, пока не будет перемещено. При перемещении сошки автоматически убираются.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Автоогонь / Ор.кр.калибра; Урон: 5d6; Магазин: 500 Винтовка; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
