    "notes": "Любой боеприпас,\nСтреляет стрелами\n\nЭкзотическая комбинация арбалета и штурмовой винтовки. Режим штурмовой винтовки не поддерживает Автоматический огонь, в его магазине всего 10 патронов, и он стреляет с помощью навыка Стрельбы из лука вместо Тактического Оружия, несмотря на то, что стреляет пулями. Оба режима этого оружия имеют встроенный Снайперский прицел и могут заряжаться Нестандартными боеприпасами, несмотря на то, что оно является Экзотическим Оружием.\nИсточник: Черный Хром\n\nПараметры источника: Навык: Лук; Урон: 4d6 / 5d6; Магазин: 10 Винтовка / 1 Стрела; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 500eb / (Дорогое)",
