    "ammoType": "—",
    "concealable": true,
    "costEb": 200,
    "notes": "Ты будешь напевать заставку этого любимого детского аниме в душе каждый раз, когда прижимаешь к груди эту прекрасно сделанную плюшевую копию героя шоу. Прямо как в аниме: стоит сжать Капитана Каддлфиша — и он выстреливает липкой стальной цепью из... ну, с нижней стороны, — чтобы цеплять злодеев и вырывать у них оружие! А самое крутое — Sanroo продаёт десятки коллекционных и брендированных нарядов, так что ты можешь приодеть Капитана Каддлфиша в стиле своей любимой поп-звезды, героя аниме или мультяшного маскота!\nЭто одноручное экзотическое лёгкое оружие ближнего боя, способное атаковать ближним боем с расстояния до 10 м (5 клеток). Когда используется для прицельного выстрела по предмету в руках (см. CP:R стр. 170), атака совершается с модификатором –6 вместо –8, не требует нанесения урона, чтобы быть успешной, и при удачном броске предмет оказывается в руках пользователя. Не может быть встроено в киберимплант.\nДополнительные костюмы для Капитана Каддлфиша стоят 20 eb (обычные) или 50 eb (дорогие) каждый — в зависимости от их редкости и ценности для коллекционеров.\nИсточник: THE 12 DAYS OF CUTIEMAS\n\nПараметры источника: Тип: Лёгкое; Урон: 1d6; ROF: 2; Руки: 1; Можно Скрыть: ДА; Цена: 200eb (Премиум)",
