    "notes": "Двуручное Экзотическое Очень Тяжелое Оружие Ближнего Боя Высокого Качества. При наличии подходящего биометрического ключа, урон, наносимый этим оружием, полностью игнорирует броню цели, если она ниже 11 ОС. С Бронёй 11 ОС и выше взаимодействует как обычно. Высокотехнологичная катана с почти прозрачным кристаллическим лезвием, микроскопически обработанная кромка которой армирована орбитальным кристаллом и способна вибрировать с частотой четыре тысячи раз в минуту, когда за рукоятку берется пользователь с правильным биометрическим ключом. В руках пользователя без правильного биометрического ключа клинок не вибрирует, оставаясь лишь Двуручным Экзотическим Очень Тяжелым Оружием Ближнего Боя Высокого Качества. Также при покупке в рукоять можно бесплатно установить лазер любого цвета, который будет преломляться в кристальном лезвии, придавая ему яркое неоновое свечение. Самый популярный цвет — красный.\nИсточник: Corebook\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 5000eb (Роскошь)",
