    "notes": "Оснащена биометрическим ключом в рукоятке.\nВ руках пользователя с корректным биометрическим ключом игнорирует броню ниже 7 ОС.\nВ руках пользователя без правильного биометрического ключа клинок остается лишь Экзотическим Одноручным Очень Тяжелым Оружием Ближнего Боя.\nИсточник: Черный Хром\n\nПараметры источника: Тип: О.Тяжелое; Урон: 4d6; ROF: 1; Руки: 2; Можно Скрыть: НЕТ; Цена: 1000eb(Оч.Дорогое)",
    "quality": "Standard",
    "skillId": "melee_weapon",
