    "notes": "Классификация: штурмовая винтовка отличного качества\nТаблица дальности: боевая винтовка\nОсобые режимы огня: автоогонь (штурмовая винтовка 4), подавляющий огонь\nСвободные слоты: 0\nПриспособления: коннектор смартлинка, снайперский прицел\nОсобые свойства: нет\n\nБоевая винтовка, прицельно и агрессивно продвигаемая среди работающих соло. Согласно утёкшим внутренним документам, после продиктованной данными гиперреакции маркетингового отдела Militech не поскупилась на производство Mountain Goat, стремясь защитить свою нишу от атак со стороны новых конкурентов в ценовом диапазоне около 2 000eb.\n\nПараметры источника: Навык (одиночного выстрела): Длинноствольное оружие; Урон: 5d6; Магазин: 25; ROF: 1; Руки: 2; Можно Скрыть: Нет; Цена: 1 550eb (Очень дорого)",
