    "notes": "Классификация: пулемет\nТаблица дальности: штурмовая винтовка\nОсобые режимы огня: автоогонь (штурмовая винтовка 5), подавляющий огонь\nСвободные слоты: 3\nПриспособления: нет\nОсобые свойства: для стрельбы из этого оружия требуется ТЕЛО 11 или выше, если только оно не установлено на крепление или стрелок не находится в положении лёжа. Кочевник может выбрать это оружие при первичной установке крепления для тяжёлого оружия на транспорт.\n\nНестандартная версия штатного оружия охранных подразделений СовОил, которое чаще всего можно увидеть установленным на их наземной технике и вертолётах. Огромный короб подачи боеприпасов оснащён сложной магнитной системой поддержки, благодаря которой перезарядка в бою становится хоть и адской, но всё же выполнимой. Её эксцентричный конструктор, Александр Петров, фанат железнодорожных моделей и владелец собственной марки водки Silver Ounce. Это оружие стало его последней разработкой для Техтроника Россия перед тем, как он сбежал в Северную Калифорнию и обрёл независимость.\n\nПараметры источника: Навык (одиночного выстрела): Тяжёлое оружие; Урон: 5d6; Магазин: 500; ROF: 1; Руки: 2; Можно Скрыть: Нет; Цена: 3 000eb (Роскошь)",
