    "notes": "Классификация: пулемёт плохого качества\nТаблица дальности: пистолет-пулемёт\nОсобые режимы огня: автоогонь (пистолет-пулемёт 5), подавляющий огонь\nСвободные слоты: 3\nПриспособления: нет\nОсобые свойства: это оружие нельзя использовать для одиночного выстрела, если в предыдущем ходу оно стреляло автоогонём. Если в предыдущем ходу оружие стреляло одиночным, в этом ходу считай его оружием отличного качества. Для стрельбы из этого оружия требуется ТЕЛО 8 или выше, если только оно не установлено на крепление. Кочевник может выбрать это оружие при первичной установке крепления для тяжёлого оружия на транспорт.\n\nЭто массивное напечатанное оружие. Поразительно эргономичный металлический череп крысы с парой стволов, вырывающихся из глазниц — работа дизайнера BlueRaven, ранее известной под сетевым псевдонимом JayeZK. Scatter Ratter — амбициозный первый проект автора под новым именем и брендом. Мы в Midnight Arms с удовольствием поддержали следующий шаг этого восходящего дизайнера и с интересом ждём её новых работ.\n\nПараметры источника: Навык (одиночного выстрела): Тяжёлое оружие; Урон: 4d6; Магазин: 56; ROF: 2; Руки: 2; Можно Скрыть: Нет; Цена: 2 552eb (Очень дорого)",
    "quality": "Poor",
    "skillId": "heavy_weapons",
    "sourceUrl": "https://alec-leon.github.io/data-pool/equipment/weapons/#weapons-solo",
