    "notes": "Классификация: очень тяжёлый пистолет отличного качества\nТаблица дальности: укороченный пистолет\nОсобые режимы огня: автоогонь (автоматический пистолет 4)\nСвободные слоты: 1\nПриспособления: барабанный магазин, автоспуск пистолета\nОсобые свойства: нет\n\nВерный друг для тех, у кого есть горящие проблемы, требующие решения на близкой дистанции. Big Boomer — это переосмысление штатного оружия времён Четвёртой корпоративной войны с новым укороченным стволом. В основу дизайна легли результаты опроса клиентов, разосланного всем, кто легально приобрёл Boomer Buster в 2044 году — аудитории, мягко говоря, не вполне отражающей реальную массовую базу покупателей.\n\nПараметры источника: Навык (одиночного выстрела): Короткоствольное оружие; Урон: 4d6; Магазин: 28; ROF: 1; Руки: 1; Можно Скрыть: Нет; Цена: 1 100eb (Дорого)",
