    "notes": "Этот универсальный и легко доступный пистолет, разработанный компанией «Конститьюшионал Армс», разрешил бесчисленные споры по всему Ночному городу. Чтобы выиграть спор, достаточно одного удачного выстрела. Навсегда.\nЭкзотический Тяжелый Пистолет с Силовым-Улучшением. Имеет магазин на 12 выстрелов. При использовании этого оружия для совершения Прицельного выстрела его урон увеличивается до 4d6.\n\nПараметры источника: Навык: Пистолет; Урон: 3d6 / 4d6; Магазин: 12 Т Пистолет; ROF: 2; Руки: 1; Можно Скрыть: ДА; Цена: 500eb / (Дорогое)",
