    "costEb": 1000,
    "notes": "Дробь 3d6\n\nОдного вида Militech Crusher достаточно, чтобы вызвать слезы на глазах у любого любителя оружия. Этот мощный дробовик, предназначенный для боя на ближней дистанции, был впервые создан в 2020 году и вскоре стал одним из самых знаковых видов оружия того времени. Версия, доступная в настоящее время на рынке, претерпела некоторые обновления по сравнению с оригиналом, но ее отличительный внешний вид остался прежним.\nЭкзотический Очень Тяжелый Пистолет с Силовым-Улучшением. Он имеет магазин на 12 выстрелов и может стрелять только дробью.\n\nПараметры источника: Навык: Пистолет; Урон: 3d6; Магазин: 12 Дробовик; ROF: 1; Руки: 1; Можно Скрыть: НЕТ; Цена: 1000eb / (Оч.Дорогое)",
